// Add JSON body parsing middleware
app.use(express.json());

// Evaluate a caller-supplied rule expression against the request.
function evalRule(req) {
  const expr = req.body.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req); // dynamic eval
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// POST /check endpoint for rule evaluation
app.post('/check', (req, res) => {
  try {
    // Check if rule is provided in request body
    if (!req.body || !req.body.rule) {
      return res.status(400).json({ error: 'Missing "rule" field in request body' });
    }

    // Evaluate the rule
    const result = evalRule(req);

    // Return the evaluation result
    res.json({ 
      result: result,
      evaluated: true,
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    // Handle evaluation errors
    res.status(400).json({ 
      error: 'Rule evaluation failed',
      message: error.message,
      evaluated: false,
      timestamp: new Date().toISOString()
    });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

