// Test script to verify the POST /check endpoint
const app = require('./app.js');
const request = require('supertest');

// Start the server for testing
const server = app.listen(3001);

async function testCheckEndpoint() {
  console.log('Testing POST /check endpoint...\n');

  // Test 1: Basic rule evaluation
  console.log('Test 1: Basic rule evaluation (ctx.amount > 100)');
  const response1 = await request(server)
    .post('/check')
    .send({
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    });

  console.log(`Status: ${response1.status}`);
  console.log(`Response: ${JSON.stringify(response1.body)}`);
  console.log(`Expected result: true\n`);

  // Test 2: Rule evaluation with request context
  console.log('Test 2: Rule evaluation with request context');
  const response2 = await request(server)
    .post('/check')
    .send({
      rule: 'ctx.user.role === "admin" && req.method === "POST"',
      context: { user: { role: 'admin' } }
    });

  console.log(`Status: ${response2.status}`);
  console.log(`Response: ${JSON.stringify(response2.body)}`);
  console.log(`Expected result: true\n`);

  // Test 3: Missing rule field
  console.log('Test 3: Missing rule field');
  const response3 = await request(server)
    .post('/check')
    .send({
      context: { amount: 150 }
    });

  console.log(`Status: ${response3.status}`);
  console.log(`Response: ${JSON.stringify(response3.body)}`);
  console.log(`Expected: 400 Bad Request\n`);

  // Test 4: Invalid rule expression
  console.log('Test 4: Invalid rule expression');
  const response4 = await request(server)
    .post('/check')
    .send({
      rule: 'ctx.amount >',
      context: { amount: 150 }
    });

  console.log(`Status: ${response4.status}`);
  console.log(`Response: ${JSON.stringify(response4.body)}`);
  console.log(`Expected: 400 Bad Request (syntax error)\n`);

  server.close();
  console.log('Tests completed.');
}

// Run test if this script is executed directly
if (require.main === module) {
  testCheckEndpoint().catch(console.error);
}

module.exports = testCheckEndpoint;

