// Simple test to verify the evalRule function logic
console.log('Testing evalRule function logic...\n');

// Mimic the evalRule function from app.js
function evalRule(req) {
  const expr = req.body.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req); // dynamic eval
}

// Test cases
const testCases = [
  {
    name: 'Basic numeric comparison',
    req: {
      body: {
        rule: 'ctx.amount > 100',
        context: { amount: 150 }
      }
    },
    expected: true
  },
  {
    name: 'String comparison',
    req: {
      body: {
        rule: 'ctx.user.role === "admin"',
        context: { user: { role: 'admin' } }
      }
    },
    expected: true
  },
  {
    name: 'Multiple conditions',
    req: {
      body: {
        rule: 'ctx.score >= 80 && ctx.attendance > 0.75',
        context: { score: 85, attendance: 0.8 }
      }
    },
    expected: true
  },
  {
    name: 'Using request method',
    req: {
      body: {
        rule: 'req.method === "POST"',
        context: {}
      },
      method: 'POST'
    },
    expected: true
  }
];

// Run tests
let passed = 0;
let failed = 0;

testCases.forEach((testCase, index) => {
  console.log(`Test ${index + 1}: ${testCase.name}`);
  console.log(`Rule: ${testCase.req.body.rule}`);
  console.log(`Context: ${JSON.stringify(testCase.req.body.context)}`);

  try {
    const result = evalRule(testCase.req);
    const success = result === testCase.expected;

    console.log(`Result: ${result}`);
    console.log(`Expected: ${testCase.expected}`);
    console.log(`Status: ${success ? '✓ PASS' : '✗ FAIL'}\n`);

    if (success) {
      passed++;
    } else {
      failed++;
    }
  } catch (error) {
    console.log(`Error: ${error.message}`);
    console.log(`Status: ✗ FAIL\n`);
    failed++;
  }
});

console.log(`\nTest Summary:`);
console.log(`Total: ${testCases.length}`);
console.log(`Passed: ${passed}`);
console.log(`Failed: ${failed}`);

if (failed === 0) {
  console.log('✅ All tests passed! The evalRule function is working correctly.');
} else {
  console.log('❌ Some tests failed. Check the implementation.');
}

