#!/usr/bin/env node

const http = require('http');

// Test 1: Simple rule without context
const test1 = {
  rule: 'ctx.amount > 100',
  context: { amount: 150 }
};

// Test 2: Rule using request properties
const test2 = {
  rule: 'req.headers["user-agent"] && req.headers["user-agent"].includes("Chrome")',
  context: {}
};

// Test 3: Invalid rule (should error)
const test3 = {
  rule: 'invalid syntax!',
  context: {}
};

// Test 4: Missing rule (should error)
const test4 = {};

function sendRequest(testData, testName) {
  const data = JSON.stringify(testData);

  const options = {
    hostname: 'localhost',
    port: 3000,
    path: '/check',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': data.length,
      'User-Agent': 'TestClient/Chrome'
    }
  };

  const req = http.request(options, (res) => {
    let responseData = '';

    res.on('data', (chunk) => {
      responseData += chunk;
    });

    res.on('end', () => {
      console.log(`\n=== ${testName} ===`);
      console.log(`Status: ${res.statusCode}`);
      console.log(`Response: ${responseData}`);
    });
  });

  req.on('error', (error) => {
    console.log(`\n=== ${testName} ===`);
    console.error(`Request error: ${error.message}`);
  });

  req.write(data);
  req.end();
}

// Start tests
console.log('Testing POST /check endpoint...\n');

// Wait a moment for server to start if needed
setTimeout(() => {
  sendRequest(test1, 'Test 1: Amount check (150 > 100)');

  setTimeout(() => {
    sendRequest(test2, 'Test 2: User-Agent check');

    setTimeout(() => {
      sendRequest(test3, 'Test 3: Invalid syntax (should fail)');

      setTimeout(() => {
        sendRequest(test4, 'Test 4: Missing rule (should fail)');
      }, 1000);
    }, 1000);
  }, 1000);
}, 1000);

