        context: { user: { age: 25, country: 'US' } }
      });

    console.log('Response:', JSON.stringify(response2.body, null, 2));
    console.log('Status:', response2.status);
    console.log('Expected: result should be true\n');

    // Test 3: Rule with request context
    console.log('Test 3: Rule with request context');
    const response3 = await request(testApp)
      .post('/check')
      .set('X-User-ID', '12345')
      .send({
        rule: 'req.get("X-User-ID") === "12345"',
        context: {}
      });

    console.log('Response:', JSON.stringify(response3.body, null, 2));
